import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const distDir = path.resolve(__dirname, '../impulso_app/dist');
const assetFiles = fs.readdirSync(path.join(distDir, 'assets'));
const cssFile = assetFiles.find(f => f.endsWith('.css'));
const cssContent = fs.readFileSync(path.join(distDir, 'assets', cssFile), 'utf8');

const jsFile = assetFiles.find(f => f.endsWith('.js'));
const jsContent = fs.readFileSync(path.join(distDir, 'assets', jsFile), 'utf8');

const completeHtml = `<!DOCTYPE html>
<html class="dark h-full w-full overflow-hidden" lang="es" style="height: 100%; width: 100%; overflow: hidden;">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover" />
  <meta name="theme-color" content="#041108" />
  <title>ImpuApp | Kinetic Interval</title>

  <!-- Google Fonts: Montserrat, Anybody & Space Grotesk -->
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Montserrat:ital,wght@0,300;0,400;0,500;0,600;0,700;0,800;0,900;1,400;1,700;1,900&family=Anybody:ital,wght@0,400;0,700;0,800;0,900;1,800&family=Space+Grotesk:wght@400;500;700&display=swap" rel="stylesheet" />
  <link href="https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:wght,FILL@100..700,0..1&display=swap" rel="stylesheet" />

  <!-- Catch any runtime errors and send to React Native / log -->
  <script>
    window.onerror = function(msg, url, line, col, error) {
      if (window.ReactNativeWebView) {
        window.ReactNativeWebView.postMessage(JSON.stringify({
          type: 'LOG_ERROR',
          message: msg + ' (' + line + ':' + col + ')'
        }));
      }
    };
  </script>

  <!-- Inlined Tailwind CSS v4 Theme -->
  <style>
${cssContent}
  </style>
</head>
<body class="bg-background text-on-surface h-full w-full overflow-hidden flex flex-col selection:bg-primary-container selection:text-on-primary-container antialiased select-none" style="background-color: #041108; color: #cceed2; margin: 0; padding: 0; height: 100%; width: 100%; overflow: hidden;">
  <div id="app" class="w-full h-full flex flex-col overflow-hidden relative" style="height: 100%; width: 100%;"></div>

  <!-- Inlined App Bundle -->
  <script>
${jsContent}
  </script>
</body>
</html>`;

const exportCode = `// Autogenerated inline bundle for Expo Go
export const APP_HTML = ${JSON.stringify(completeHtml)};
`;

fs.writeFileSync(path.join(__dirname, 'appHtml.js'), exportCode, 'utf8');
console.log('App bundle successfully generated for Expo in appHtml.js');
